create function public.fechou_import_deals(p_workspace uuid,p_rows jsonb) returns integer language plpgsql security invoker set search_path='' as $$ declare r record; v_count int:=0; begin if public.fechou_role(p_workspace) is null or jsonb_typeof(p_rows) is distinct from 'array' then raise exception 'Importação não autorizada.'; end if; if jsonb_array_length(p_rows) not between 1 and 500 then raise exception 'Inclua de 1 a 500 linhas.'; end if; for r in select * from jsonb_to_recordset(p_rows) as t(id uuid,owner_id uuid,stage_id uuid,company text,contact text,email text,phone text,segment text,linkedin text,instagram text,founded_on date,birth_date date,notes text,amount numeric) loop if r.id is null then insert into public.fechou_deals(workspace_id,owner_id,stage_id,company,contact,email,phone,segment,linkedin,instagram,founded_on,birth_date,notes,amount) values(p_workspace,r.owner_id,r.stage_id,r.company,r.contact,r.email,r.phone,r.segment,r.linkedin,r.instagram,r.founded_on,r.birth_date,r.notes,r.amount); else update public.fechou_deals set stage_id=r.stage_id,company=r.company,contact=r.contact,email=r.email,phone=r.phone,segment=r.segment,linkedin=r.linkedin,instagram=r.instagram,founded_on=r.founded_on,birth_date=r.birth_date,notes=r.notes,amount=r.amount where workspace_id=p_workspace and id=r.id; if not found then raise exception 'Oportunidade não encontrada na linha %.',v_count+2; end if; end if; v_count:=v_count+1; end loop; return v_count; end $$;
revoke all on function public.fechou_import_deals(uuid,jsonb) from public, anon;
grant execute on function public.fechou_import_deals(uuid,jsonb) to authenticated;